            if res[i] != '?':
                continue
            banned = set()
            if i > 0:
                banned.add(res[i - 1])
            if i + 1 < n:
                banned.add(res[i + 1])
            for code in range(97, 123):
                c = chr(code)
                if c not in banned:
                    res[i] = c
                    break
        return ''.join(res)

