class Solution {
public:
    string modifyString(string s) {
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] != '?') continue;
            bool banned[26] = {false};
            if (i > 0 && s[i - 1] != '?') banned[s[i - 1] - 'a'] = true;
            if (i + 1 < n && s[i + 1] != '?') banned[s[i + 1] - 'a'] = true;
            for (char c = 'a'; c <= 'z'; c++) {
                if (!banned[c - 'a']) {
                    s[i] = c;
                    break;
                }
            }
        }
        return s;
    }
};

