var modifyString = function(s) {
    const arr = s.split('');
    const n = arr.length;
    for (let i = 0; i < n; i++) {
        if (arr[i] !== '?') continue;
        const banned = new Set();
        if (i > 0 && arr[i - 1] !== '?') banned.add(arr[i - 1]);
        if (i + 1 < n && arr[i + 1] !== '?') banned.add(arr[i + 1]);
        for (let code = 97; code <= 122; code++) {
            const c = String.fromCharCode(code);
            if (!banned.has(c)) {
                arr[i] = c;
                break;
            }
        }
    }
    return arr.join('');
};
